        ScrollView scroll=new ScrollView(this);scroller=scroll;scroll.setFillViewport(true);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));body=column();body.setPadding(dp(22),0,dp(22),dp(28));scroll.addView(body);
        nav=new LinearLayout(this);nav.setBackgroundColor(Color.rgb(18,18,20));nav.setPadding(dp(8),dp(6),dp(8),dp(6));String[] glyphs={"⌂","▦","◷","⌕","⋯"};int slot=0;for(String label:new String[]{"Home","Library","History","Discover","More"}){boolean selected=page.equals(label)||label.equals("More")&&(page.equals("Settings")||page.equals("More"));android.text.SpannableString caption=new android.text.SpannableString(glyphs[slot++]+"\n"+label);caption.setSpan(new android.text.style.RelativeSizeSpan(1.9f),0,1,0);TextView t=text("",11,selected?GOLD:MUTED);t.setText(caption);t.setLineSpacing(0,1);t.setGravity(Gravity.CENTER);t.setPadding(0,dp(6),0,dp(6));if(selected)t.setBackground(bg(Color.rgb(44,39,32),dp(14)));t.setContentDescription(label);t.setOnClickListener(v->{if(label.equals("Discover")){startActivity(new Intent(this,DiscoverActivity.class));return;}page=label;detail="";search="";render();});LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(0,dp(56),1);np.setMargins(dp(3),0,dp(3),0);nav.addView(t,np);}root.addView(nav);
        if(page.equals("Settings")){settings();return;}if(page.equals("More")){titleActions.more();return;}if(!detail.isEmpty()){details();return;}
        if(data.items().length()==0){heading("Your cinema, anywhere.");paragraph("Bring your Noir library, history and exact resume times to your phone. Your posters stay here even when the videos are gone.");body.addView(button("Pair with my PC",this::pairInput,true));paragraph("First version · Home Wi-Fi sync · Android 8 or later");return;}
